(window.webpackJsonp=window.webpackJsonp||[]).push([[261],{679:function(_,v,t){"use strict";t.r(v);var p=t(1),r=Object(p.a)({},(function(){var _=this,v=_.$createElement,t=_._self._c||v;return t("ContentSlotsDistributor",{attrs:{"slot-key":_.$parent.slotKey}},[t("h1",{attrs:{id:"暖文-▍《疯娘》"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#暖文-▍《疯娘》"}},[_._v("#")]),_._v(" 暖文 ▍《疯娘》")]),_._v(" "),t("p",[_._v("终于等到你")]),_._v(" "),t("p",[_._v("还好没放弃")]),_._v(" "),t("p",[t("img",{attrs:{src:"https://mmbiz.qpic.cn/mmbiz_jpg/eb5b3BxcT6Xv55w1yuPjHGk06tg5RMEB9RFJhtTLUxtYOajiaeSCv0HVW0tFxoKiaWub1SADmNrVKN9mNiaQkfvCA/640?wx_fmt=jpeg&wxfrom=5&wx_lazy=1&wx_co=1",alt:"图片"}})]),_._v(" "),t("p",[_._v("《疯娘》是王恒绩于2004年底创作的5000字的小说，2005年在北京人民大会堂被评为全国“敬老好文章”，获得全国一等奖。国家领导人颁奖，并被编入了大学语文，同时被海内外五六十家影视公司抢购影视版权，还被翻译成了四十多国文字。")]),_._v(" "),t("p",[_._v("疯娘")]),_._v(" "),t("p",[_._v("23年前，有个年轻的女子流落到我们村，蓬头垢面，见人就傻笑，且毫不避讳地当众小便。因此，村里的媳妇们常对着那女子吐口水，有的媳妇还上前踹几脚，叫她“滚远些”。可她就是不走，依然傻笑着在村里转悠。 那时，我父亲已有35岁。他曾在石料场干活被机器绞断了左手，又因家穷，一直没娶媳妇。奶奶见那女子还有几分姿色，就动了心思，决定收下她给我父亲做媳妇，给我家“续上香火”。父亲虽老大不情愿，但看着家里这番光景，咬咬牙还是答应了。结果，父亲一分未花，就当了新郎。")]),_._v(" "),t("p",[t("img",{attrs:{src:"http://mmbiz.qpic.cn/mmbiz_png/HhCBws2kMsBupr4HFVhDAor9RReOtwEuwzv2EYHK5eb6FrROKsibI7UxpCMEDPKtV7HAD18MHPTUNh25Gt2QqRw/640?wx_fmt=png&wxfrom=5&wx_lazy=1&wx_co=1",alt:"图片"}})]),_._v(" "),t("p",[_._v("2")]),_._v(" "),t("p",[_._v("娘生下我的时候，奶奶抱着我，瘪着没剩几颗牙的嘴欣喜地说：“这疯婆娘，还给我生了个带把儿的孙子”。只是，我一生下来，奶奶就把我抱走了，而且从不让娘靠近。")]),_._v(" "),t("p",[_._v("娘一直想抱抱我，多次在奶奶面前吃力地喊：“给，给我……”奶奶没理她。我那么小，像个肉嘟嘟，万一娘失手把我掉在地上怎么办？毕竟，娘是个疯子。每当娘有抱我的请求时，奶奶总瞪起眼睛训她：“你别想抱孩子，我不会给你的。要是我发现你偷抱了他，我就打死你。即使不打死，我也要把你撵走。”奶奶说这话时，没有半点儿含糊的意思。娘听懂了，满脸的惶恐，每次只是远远地看着我。尽管娘的奶胀得厉害，可我没能吃到娘的半口奶水，是奶奶一匙一匙把我喂大的。奶奶说娘的奶水里有“神经病”，要是传染给我就麻烦了。")]),_._v(" "),t("p",[_._v("那时，我家依然在贫困的泥潭里挣扎。特别是添了娘和我后。奶奶决定把娘撵走，因为娘不但在家吃“闲饭”，时不时还惹是生非。一天，奶奶煮了一大锅饭，亲手给娘添了一大碗，说：“媳妇儿，这个家太穷了，婆婆对不起你。你吃完这碗饭，就去找个富点儿的人家过日子，以后也不准来了，啊？”娘刚扒拉一大团饭在口里，听了奶奶下的“逐客令”。显得非常吃惊，一团饭就在嘴里凝滞了。娘望着奶奶怀中的我，口齿不清地哀叫：“不，不要……”奶奶猛地沉下脸，拿出威严的家长作风厉声吼道：“你这个疯婆娘，犟什么犟，犟下去没你的好果子吃。你本来就是到处流浪的，我收留了你两年了，你还要怎么样？吃完饭就走，听到没有？”说完奶奶从门后拿出一柄锄，像佘太君的龙头杖似的往地上重重一磕，“咚”地发出一声响。娘吓了一大跳，怯怯地看着婆婆，又慢慢低下头去看面前的饭碗，有泪水落在白花花的米饭上。在奶奶逼视下，娘突然有个很奇怪的举动，她将碗中的饭分了一大半给另一只空碗，然后可怜巴巴地看着奶奶。")]),_._v(" "),t("p",[_._v("奶奶呆了，原来，娘是向奶奶表示，每餐只吃半碗饭，只求别赶她走。奶奶的心仿佛被人狠狠揪了几把，奶奶也是女人，她的强硬态度也是装出来的。奶奶别过头，生生地将热泪憋了回去，然后重新板起了脸说：“快吃快吃，吃了快走。”娘似乎绝望了，连那半碗饭也没吃，踉踉跄跄地出了门，却长时间站在门前不走。奶奶硬着心肠说：“你走，你走，不要回头。”娘反而走拢来，一双手伸向婆婆怀里，原来，娘想抱抱我。奶奶犹豫了一下，还是将襁褓中的我递给了娘。娘第一次将我搂在怀里，咧开嘴笑了，笑得春风满面。奶奶却如临大敌，两手在我身下接着，生怕娘的疯劲一上来，将我像扔垃圾一样丢掉。娘抱我的时间不足三分钟，奶奶便迫不及待地将我夺了过去，然后转身进屋关上了门。")]),_._v(" "),t("p",[t("img",{attrs:{src:"http://mmbiz.qpic.cn/mmbiz_jpg/HhCBws2kMsBupr4HFVhDAor9RReOtwEuaecWUI0JsW2l9ADxCg72Fna6mAFj2x5KGRAyjEucI4CQWMW1xiaOdsg/640?wx_fmt=jpeg&wxfrom=5&wx_lazy=1&wx_co=1",alt:"图片"}})]),_._v(" "),t("p",[_._v("3")]),_._v(" "),t("p",[_._v("​\t 当我懵懵懂懂地晓事时，我才发现，除了我，别的小伙伴都有娘。我找父亲要，找奶奶要，他们说，你娘死了。可小伙伴却告诉我：“你娘是疯子，被你奶奶赶走了。”我便找奶奶扯皮，要她还我娘，还骂她是“狼外婆”，甚至将她端给我的饭菜泼了一地。那时我还没有“疯”的概念，只知道非常想念她，她长什么样？还活着吗？没想到，在我六岁那年，离家5年的娘居然回来了。那天，几个小伙伴飞也似的跑来报信：“小树，快去看，你娘回来了，你的疯娘回来了。”我喜得屁颠屁颠的，撒腿就往外跑，父亲奶奶随着我也追了出来。这是我有记忆后第一次看到娘。她还是破衣烂衫，头发上还有些枯黄的碎草末，天知道是在哪个草堆里过的夜。娘不敢进家门，却面对着我家，坐在村前稻场的石磙上，手里还拿着个脏兮兮的气球。当我和一群小伙伴站在她面前时，她急切地从我们中间搜寻她的儿子。娘终于盯住我，死死地盯住我，咧着嘴叫我：“小树……球……球”她站起来，不停地扬着手中的气球，讨好地往我怀里塞。我却一个劲儿地往后退。我大失所望，没想到我日思夜想的娘居然是这样一副形象。一个小伙伴在一旁起哄说：“小树，你现在知道疯子是什么样了吧？就是你娘这样的。”")]),_._v(" "),t("p",[_._v("我气愤地对小伙伴说：“她是你娘！你娘才是疯子，你娘才是这个样子。”我扭头就跑了。这个疯娘我不要了。奶奶和父亲却把娘领进了门。当年，奶奶撵走娘后，她的良心受到了拷问，随着一天天衰老，她的心再也硬不起来，所以主动留下了娘，而我老大不乐意，因为娘丢了我的面子。")]),_._v(" "),t("p",[_._v("我从没给娘好脸色看，从没跟她主动说过话，更没有喊她一声“娘”，我们之间的交流是以我“吼”为主，娘是绝不敢顶嘴的。")]),_._v(" "),t("p",[_._v("4")]),_._v(" "),t("p",[_._v("​\t家里不能白养着娘，奶奶决定训练娘做些杂活。下地劳动时，奶奶就带着娘出去“观摩”，稍不听话就要挨打。")]),_._v(" "),t("p",[_._v("过了些日子，奶奶以为娘已被自己训练得差不多了，就叫娘单独出去割猪草。没想到，娘只用了半小时就割了两筐“猪草”。奶奶一看，又急又慌，娘割的是人家田里正生浆拔穗的稻谷。奶奶气急败坏地骂她“疯婆娘谷草不分……”奶奶正想着如何善后时，稻田的主人找来了，竟说是奶奶故意教唆的。奶奶火冒三丈，当着人家的面拿出根棒槌一下敲在娘的后腰上，说：“打死你这个疯婆娘，你给老娘些……”")]),_._v(" "),t("p",[_._v("娘虽疯，疼还是知道的，她一跳一跳地躲着奶奶的棒槌，口里不停地发出“别、别……”的哀号。最后，人家看不过眼，主动说“算了，我们不追究了。以后把她看严点就是……”这场风波平息后，娘歪在地上抽泣着。我鄙夷地对她说：“草和稻子都分不清，你真是个猪。”话音刚落，我的后脑勺挨了一巴掌，是奶奶打的。奶奶瞪着眼骂我：“小兔崽子，你怎么说话的？再怎么着，她也是你娘啊！”我不屑地嘴一撇：“我没有这样的傻疯娘！”")]),_._v(" "),t("p",[_._v("“嗬，你真是越来越不像话了。看我不打你！”奶奶又举起巴掌，这时只见娘像弹簧一样从地上跳起，横在我和奶奶中间，娘指着自己的头，“打我、打我”地叫着。")]),_._v(" "),t("p",[_._v("我懂了，娘是叫奶奶打她，别打我。奶奶举在半空中的手颓然垂下，嘴里喃喃地说道：“这个疯婆娘，心里也知道疼爱自己的孩子啊！”我上学不久，父亲被邻村一位养鱼专业户请去守鱼池，每月能赚50元。娘仍然在奶奶带领下出门干活，主要是打猪草，她没再惹什么大的乱子。")]),_._v(" "),t("p",[t("img",{attrs:{src:"http://mmbiz.qpic.cn/mmbiz_jpg/HhCBws2kMsBupr4HFVhDAor9RReOtwEuibwNGWSNKmgWlVVJiaSqZS6icj1VHniaOPUaffDjIXqCKKeG6INQ3S7BxQ/640?wx_fmt=jpeg&wxfrom=5&wx_lazy=1&wx_co=1",alt:"图片"}})]),_._v(" "),t("p",[_._v("5")]),_._v(" "),t("p",[_._v("记得我读小学三年级时一个冬日，天空突然下起了雨，奶奶让娘给我送雨伞。娘可能一路摔了好几跤，浑身像个泥猴似的，她站在教室的窗户旁望着我傻笑，口里还叫：“树……伞……”一些同学嘻嘻地笑。带头起哄的是小范，当他还在夸张地模仿时，我抓起面前的文具盒，猛地向他砸过去。他冲上前来掐住我的脖子，我俩厮打起来。我个子小，根本不是他的对手，被他轻易压在地上。这时，只听教室外传来“嗷”的一声长啸，娘像个大侠似的飞跑进来，一把抓起小范，拖到了屋外。都说疯子力气大，真是不假。娘双手将欺负我的小范举向半空，他吓得哭爹喊娘，一双胖乎乎的小腿在空中乱踢蹬。娘毫不理会，居然将他丢到了学校门口的水塘里，然后一脸漠然地走开了。")]),_._v(" "),t("p",[_._v("娘为我闯了大祸，她却像没事似的。在我面前，娘又恢复了一副怯怯的神态，讨好地看着我。我明白这就是母爱，即使神志不清，母爱也是清醒的，因为她的儿子遭到了别人的欺负。当时我情不自禁地叫了声：“娘！”这是我会说话以来第一次喊她。娘浑身一震，久久地看着我，然后像个孩子似的羞红了脸，咧了咧嘴，傻傻地笑了。那天，我们母子俩第一次共撑一把伞回家。我把这事跟奶奶说了，奶奶吓得跌倒在椅子上，连忙请人去把爸爸叫了回来。爸爸刚进屋，一群拿着刀棒的壮年男人闯进我家，不分青红皂白，先将锅碗瓢盆砸了个稀巴烂。这都是范家请来的人，范父恶狠狠地指着爸爸的鼻子说：“我儿子吓出了神经病，现在卫生院躺着。你家要不拿出1000块钱的医药费，我一把火烧了你家的房子。”")]),_._v(" "),t("p",[_._v("1000块？爸爸每月才50块钱啊！看着杀气腾腾的范家人，爸爸的眼睛慢慢烧红了，他用非常恐怖的目光盯着娘，一只手飞快地解下腰间的皮带，劈头盖脸地向娘打去。一下又一下，娘像只惶惶偷生的老鼠，无助地跳着、躲着，她发出的凄厉声以及皮带抽在她身上发出的那种清脆的声响，我一辈子都忘不了。最后还是派出所所长赶来制止了爸爸施暴的手。派出所的调解结果是，双方互有损失，两不亏欠。谁再闹就抓谁！一帮人走后，爸看看满屋狼藉的锅碗碎片，又看看伤痕累累的娘，他突然将娘搂在怀里痛哭起来，说：“疯婆娘，不是我硬要打你，我要不打你，这事下不了地，咱们没钱赔人家啊。”爸又看着我说：“树儿，你一定要争气。要不，咱们就这样被人欺负一辈子啊！”我懂事地点点头。")]),_._v(" "),t("p",[t("img",{attrs:{src:"http://mmbiz.qpic.cn/mmbiz_png/HhCBws2kMsBupr4HFVhDAor9RReOtwEu8GFJvLNNUWRwOEoMMEcBqYjWNu0xF3JIVSCLRENtI2NLIcBg4DubUw/640?wx_fmt=png&wxfrom=5&wx_lazy=1&wx_co=1",alt:"图片"}})]),_._v(" "),t("p",[_._v("6")]),_._v(" "),t("p",[_._v("2000年夏，我以优异成绩考上了高中。积劳成疾的奶奶不幸去世，家里的日子更难了。民政局将我家列为特困家庭，每月补助40元钱，我所在的高中也适当减免了我的学杂费，我这才得以继续读下去。")]),_._v(" "),t("p",[_._v("由于是住读，学习又抓得紧，我很少回家。父亲依旧在为50元打工，为我送菜的担子就责无旁贷地落在娘身上。每次总是隔壁的婶婶帮忙为我炒好咸菜，然后交给娘送来。20公里的羊肠山路亏娘牢牢地记了下来，风雨无阻。也真是奇迹，凡是为儿子做的事，娘一点儿也不疯。除了母爱，我无法解释这种现象在医学上应该怎么破译。")]),_._v(" "),t("p",[_._v("2003年4月的一个星期天，娘来了，不但为我送来了菜，还带来了十几个野鲜桃。我拿起一个，咬了一口，笑着问她：“挺甜的，哪来的？”娘说：“我……我摘的……”没想到娘还会摘野桃，我由衷地表扬她：“娘，您真是越来越能干了。”娘嘿嘿地笑了。")]),_._v(" "),t("p",[_._v("娘临走前，我照例叮嘱她注意安全，娘“哦哦”地应着。送走娘，我又扎进了高考前最后的复习中。第二天，我正在上课，婶婶匆匆地赶到学校，问我娘送菜来没有，说我娘到现在还没回家。我心一紧，娘该不会走错道吧？婶婶问：“你娘没说什么？”我说没有，她给我带了十几个野鲜桃哩。婶婶两手一拍：“坏了坏了，可能就坏在这野鲜桃上。”婶婶替我请了假，我们沿着山路往回找，回家的路上确有几棵野桃树，桃树上稀稀拉拉地挂着几个桃子，因为长在峭壁上才得以保存下来。我们同时发现一棵桃树有枝丫折断的痕迹，树下是百丈深渊。婶婶看了看我说，“到峭壁底下去看看吧！”我说，“婶婶你别吓我……”婶婶不由分说，拉着我就往山谷里走……")]),_._v(" "),t("p",[_._v("娘静静地躺在谷底，周边是一些散落的桃子，她手里还紧紧攥着一个，身上的血早就凝固成了沉重的黑色。我悲痛得五脏俱裂，紧紧地抱住娘，说：“娘啊，我的苦命娘啊，儿悔不该说这桃子甜啊，是儿子要了你的命……”我将头贴在娘冰凉的脸上，哭得漫山遍野的石头都陪着落泪……")]),_._v(" "),t("p",[_._v("7")]),_._v(" "),t("p",[_._v("2003年8月7日，在娘下葬后的第100天，大学烫金的录取通知书穿过娘所走过的路，穿过那几株野桃树，穿过村前的稻场，径直“飞”进了我的家门。我把这份迟到的书信插在娘冷寂的坟头：“娘，儿出息了，您听到了吗？您可以含笑九泉了！”")])])}),[],!1,null,null,null);v.default=r.exports}}]);